-- 通用容器: 单向队列

---@class Queue
local Queue = Class('Queue')

-- 外部访问时使用:
-- local Queue = import('Game.DreamSpace.Tools.Queue')

-- ========================================================


function Queue:__init( capacity_ )
    self._deque = {} -- lua table array, 1-based
    self._firstIdx = 0 -- 指向当前 first 元素, 0 表示指空
    self._lastIdx = 0  -- 指向当前 last  元素, 0 表示指空

    self._capacity = capacity_ -- 容积
    self._count = 0 -- 元素个数
end



function Queue:__delete()
    self._deque = nil
end

-- ========================================================


function Queue:Count()
    return self._count
end


function Queue:AddLast( entry_ )

    if self._count >= self._capacity then 
        printError( "Queue 元素超载" )
        return
    end 

    if self._count == 0 then 
        self._firstIdx = 1
        self._lastIdx  = 1
    else 
        self._lastIdx = (self._lastIdx == self._capacity) and 1 or (self._lastIdx + 1)
    end 

    self._deque[self._lastIdx] = entry_
    self._count = self._count + 1
end



function Queue:PeekFirst()
    if self._count == 0 then 
        return nil
    else
        assert( isNotNull( self._deque[self._firstIdx] ) )
        return self._deque[self._firstIdx]
    end
end


function Queue:PeekLast()
    if self._count == 0 then 
        return nil
    else
        assert( isNotNull( self._deque[self._lastIdx] ) )
        return self._deque[self._lastIdx]
    end
end

function Queue:Clear()
    self._deque = {}
    self._firstIdx = 0
    self._lastIdx = 0
    self._count = 0
end

function Queue:AddFirst( entry_ )
    if self._count >= self._capacity then 
        printError( "Queue 元素超载" )
        return
    end 

    if self._count == 0 then 
        self._firstIdx = 1
        self._lastIdx  = 1
    else 
        self._firstIdx = (self._firstIdx == 1) and self._capacity or (self._firstIdx - 1)
    end 

    self._deque[self._firstIdx] = entry_
    self._count = self._count + 1
end

function Queue:RemoveLast()
    if self._count == 0 then 
        -- donothing
        return nil
    else 
        local lastEntry = self._deque[self._lastIdx]
        self._deque[self._lastIdx] = nil
        self._lastIdx = (self._lastIdx == 1) and self._capacity or (self._lastIdx - 1)
        self._count = self._count - 1
        return lastEntry
    end
end

-- ret: 依然会返回 first 元素;
function Queue:RemoveFirst()
    if self._count == 0 then 
        -- donothing
        return nil
    else 
        local firstEntry = self._deque[self._firstIdx]
        self._deque[self._firstIdx] = nil
        self._firstIdx = (self._firstIdx == self._capacity) and 1 or (self._firstIdx + 1)
        self._count = self._count - 1
        return firstEntry
    end
end


-- for debug:
function Queue:PrintAll()
    local log = "queue: \n capacity:" .. self._capacity .. ", \n count:" .. self._count .. 
                ", \n firstIdx:" .. self._firstIdx .. ", \n lastIdx:" .. self._lastIdx ..
                ", \n ------------- "

    for k,v in pairs(self._deque) do 
        log = log .. "\n    k:" .. k .. ", v:" .. v 
    end 
    print( log )
end



return Queue
